(async()=>{try{const api=await import('./final-sequence.js?v=95');if(!window.motionCheckpointReady)await new Promise(r=>window.addEventListener('motion-checkpoint-ready',r,{once:true}));for(const[k,v]of Object.entries(api.finalDefaults))if(fx[k]===undefined)fx[k]=structuredClone(v);const priorPhases=phaseTimes,priorFrame=frame,priorControls=renderDepotControls,seconds=t*settings.duration;const fire=document.createElement('video');fire.src='assets/real-fire.mp4';fire.muted=true;fire.playsInline=true;fire.preload='auto';sprites.finalFire=fire;const start=()=>priorPhases().end;phaseTimes=()=>({...priorPhases(),end:start()+(fx.finalEnabled?60/fx.finalRate:0)});for(const[k,v]of Object.entries(api.finalSources)){sources[k]='assets/'+v;const im=new Image();im.onload=()=>{base._renderKey='';frame(base,t)};im.src=sources[k];sprites[k]=im;}
frame=function(el,p){const duration=settings.duration,sec=p*duration;try{settings.duration=priorPhases().end;priorFrame(el,Math.min(sec,settings.duration-.00001)/settings.duration);}finally{settings.duration=duration;}let cv=el.querySelector('.documentaryFinal');if(!fx.finalEnabled||sec<start()){if(cv)cv.style.display='none';return;}if(!cv){cv=document.createElement('canvas');cv.width=960;cv.height=540;cv.className='tearCanvas documentaryFinal';cv.style.cssText='position:absolute;inset:0;width:100%;height:100%;pointer-events:none;z-index:56';el.append(cv);}cv.style.display='block';const age=sec-start(),state=api.finalStages.find(s=>age*fx.finalRate>=s.from&&age*fx.finalRate<s.to);for(const[id,key]of Object.entries(fx.finalBindings)){const v=sprites[key];if(v?.tagName==='VIDEO'&&v.readyState>=2&&state&&(id===state.id||id==='tv-screen')){const target=Math.max(0,age*fx.finalRate-state.from)%Math.max(.01,v.duration);if(!v.seeking&&Math.abs(v.currentTime-target)>.08)v.currentTime=target;}}if(state?.id==='unbeaten'&&fire.readyState>=2&&!fire.seeking){const target=Math.max(0,age*fx.finalRate-state.from-fx.finalFireDelay)%Math.max(.01,fire.duration);if(Math.abs(fire.currentTime-target)>.08)fire.currentTime=target;}api.paintFinal(cv.getContext('2d'),age,sprites,fx);};
function refresh(){syncDuration();saveEffects();base._renderKey='';frame(base,t);}renderDepotControls=function(){priorControls();const host=document.querySelector('#depotControls');if(!host)return;const box=document.createElement('details');box.innerHTML='<summary>15:00–16:00 · final / football · V95</summary>';host.prepend(box);for(const s of api.finalStages){const b=document.createElement('button');b.className='pill';b.textContent=s.id;b.onclick=()=>{openEditor();playing=false;t=(start()+(s.from+.1)/fx.finalRate)/settings.duration;frame(base,t);};box.append(b);}for(const[id,label]of[['handshake','Edit anatomical handshake'],['team','Edit three red players']]){const b=document.createElement('button');b.textContent=label;b.onclick=async()=>{const m=await import('./native3d/final-scenes.js');const key=id==='team'?'finalTeamScene':'finalHandshakeScene';const scene=fx[key]||(id==='team'?m.createFinalTeam():m.createFinalHandshake());globalThis.MotionNative3D?.open(scene,value=>{fx[key]=value;refresh();});};box.append(b);}const area=document.createElement('textarea');area.value=JSON.stringify(Object.fromEntries(Object.keys(api.finalDefaults).map(k=>[k,fx[k]])),null,2);area.setAttribute('aria-label','Final minute editable layers and settings');const apply=document.createElement('button');apply.textContent='Apply minute settings';apply.onclick=()=>{try{const next=JSON.parse(area.value);api.validateFinal({...fx,...next});for(const k of Object.keys(api.finalDefaults))if(next[k]!==undefined)fx[k]=next[k];refresh();}catch(e){apply.textContent=e.message;}};box.append(area,apply);const slots=document.createElement('select');for(const id of [...api.finalStages.map(s=>s.id),'tv-screen'])slots.add(new Option(id,id));const upload=document.createElement('input');upload.type='file';upload.accept='image/*,video/*';upload.onchange=async()=>{const file=upload.files[0];if(!file)return;const id=slots.value,key='final-'+id+'-'+Date.now(),url=await new Promise(r=>{const f=new FileReader();f.onload=()=>r(f.result);f.readAsDataURL(file)});await saveAsset(key,url);sources[key]=url;const im=file.type.startsWith('video/')?document.createElement('video'):new Image();im.muted=true;im.playsInline=true;im.onloadeddata=refresh;im.onload=refresh;im.onseeked=()=>frame(base,t);im.src=url;sprites[key]=im;fx.finalBindings[id]=key;refresh();};box.append(slots,upload);};registerCapability('doc-final-minute',{label:'Football final · 15:00–16:00',category:'Documentary actions',defaults:api.finalDefaults,slots:api.finalStages.map(s=>s.id),render:(c,age,layer)=>api.paintFinal(c,age,sprites,{...fx,...layer.params})});await restoreAssets();window.MotionFinal={...api,start};renderDepotControls();syncDuration();t=seconds/settings.duration;saveEffects();window.motionFinalReady=true;window.dispatchEvent(new Event('motion-final-ready'));}catch(e){console.error('Final minute',e);}})();
